frappe.ui.form.on('Patient Appointment', {
    refresh: function(frm) {
        // Override the default Create buttons with custom validation

        // First, remove the standard Create buttons that we want to control
        // This is done by finding and removing them from the DOM
        frm.page.remove_inner_button('Patient Encounter', 'Create');
        frm.page.remove_inner_button('Vital Signs', 'Create');

        // Next, add our custom buttons with payment validation
        if (["Open", "Checked In", "Confirmed"].includes(frm.doc.status) || 
            (frm.doc.status == "Scheduled" && !frm.doc.__islocal)) {

            // Check if payment required (show_payment_popup enabled)
            frappe.db.get_single_value("Healthcare Settings", "show_payment_popup")
                .then(show_payment_popup => {

                    // If payment not required, add buttons without validation
                    if (!show_payment_popup) {
                        addStandardCreateButtons(frm);
                        return;
                    }

                    // If payment is required, add buttons with validation
                    if (frm.doc.invoiced) {
                        // Payment already made, add standard buttons
                        addStandardCreateButtons(frm);
                    } else {
                        // Payment not made, add disabled buttons with warning
                        if (!frm.doc.procedure_template && !frm.doc.therapy_type) {
                            frm.add_custom_button(__('Patient Encounter'), function() {
                                showPaymentRequiredMessage();
                            }, __('Create')).addClass('btn-warning');
                        }

                        frm.add_custom_button(__('Vital Signs'), function() {
                            showPaymentRequiredMessage();
                        }, __('Create')).addClass('btn-warning');
                    }
                });
        }
    }
});

// Function to show standard create buttons (same as original functionality)
function addStandardCreateButtons(frm) {
    if (frm.doc.procedure_template) {
        frm.add_custom_button(__('Clinical Procedure'), function() {
            frappe.model.open_mapped_doc({
                method: 'healthcare.healthcare.doctype.clinical_procedure.clinical_procedure.make_procedure',
                frm: frm,
            });
        }, __('Create'));
    } else if (frm.doc.therapy_type) {
        frm.add_custom_button(__('Therapy Session'), function() {
            frappe.model.open_mapped_doc({
                method: 'healthcare.healthcare.doctype.therapy_session.therapy_session.create_therapy_session',
                frm: frm,
            });
        }, __('Create'));
    } else {
        frm.add_custom_button(__('Patient Encounter'), function() {
            frappe.model.open_mapped_doc({
                method: 'healthcare.healthcare.doctype.patient_appointment.patient_appointment.make_encounter',
                frm: frm,
            });
        }, __('Create'));
    }

    frm.add_custom_button(__('Vital Signs'), function() {
        if (!frm.doc.patient) {
            frappe.throw(__('Please select patient'));
        }
        frappe.route_options = {
            'patient': frm.doc.patient,
            'appointment': frm.doc.name,
            'company': frm.doc.company
        };
        frappe.new_doc('Vital Signs');
    }, __('Create'));
}

// Function to show payment required message
function showPaymentRequiredMessage() {
    frappe.msgprint({
        title: __('Payment Required'),
        indicator: 'red',
        message: __('Please complete payment for this appointment before creating clinical documents. Click the "Make Payment" button to process payment.')
    });
}

frappe.ui.form.on('Inpatient Record', {
    refresh: function(frm) {
        // Only show the buttons if the document is not new AND status is "Admitted"
        if (!frm.doc.__islocal && frm.doc.status === "Admitted") {
            // 1. Service Request button
            frm.add_custom_button(__("Service Request"), function() {
                frappe.call({
                    method: "healthcare.controllers.inpatient_record_requests.create_service_request",
                    args: {
                        inpatient_record: frm.doc.name
                    },
                    callback: function(r) {
                        if (r.message) {
                            frappe.new_doc("Service Request", {
                                patient: frm.doc.patient,
                                patient_name: frm.doc.patient_name,
                                gender: frm.doc.gender,
                                dob: frm.doc.dob,
                                mobile: frm.doc.mobile,
                                email: frm.doc.email,
                                company: frm.doc.company,
                                order_date: frappe.datetime.nowdate(),
                                order_time: frappe.datetime.now_time(),
                                practitioner: frm.doc.primary_practitioner,
                                source_doc: "Inpatient Record",
                                order_group: frm.doc.name,
                                inpatient_record: frm.doc.name,
                                inpatient_status: frm.doc.status
                            });
                        }
                    }
                });
            }, __('Create'));

            // 2. Consumable Requests button (renamed from Consumable/Blood Request)
            frm.add_custom_button(__("Consumable Requests"), function() {
                // Show a dialog to choose request type with the added "Medicine Request" option
                frappe.prompt([
                    {
                        fieldname: 'consumer_request_type',
                        label: __('Request Type'),
                        fieldtype: 'Select',
                        options: 'Consumable Request\nBlood Request\nMedicine Request',
                        reqd: 1,
                        default: 'Consumable Request'
                    }
                ],
                function(values) {
                    // First, get the customer associated with the patient
                    frappe.call({
                        method: "frappe.client.get_value",
                        args: {
                            doctype: "Patient",
                            filters: { name: frm.doc.patient },
                            fieldname: ["customer"]
                        },
                        callback: function(patient_data) {
                            // Now create the consumer request
                            frappe.call({
                                method: "healthcare.controllers.inpatient_record_requests.create_consumer_request",
                                args: {
                                    inpatient_record: frm.doc.name,
                                    request_type: values.consumer_request_type
                                },
                                callback: function(r) {
                                    if (r.message) {
                                        // Create a new Consumer Request with pre-filled values
                                        let doc = frappe.model.get_new_doc("Consumer Request");

                                        // Set field values
                                        doc.consumer_request_type = values.consumer_request_type;
                                        doc.patient = frm.doc.patient;
                                        doc.company = frm.doc.company;
                                        doc.transaction_date = frappe.datetime.nowdate();
                                        doc.schedule_date = frappe.datetime.nowdate();
                                        doc.title = `${values.consumer_request_type} for ${frm.doc.patient_name || frm.doc.patient}`;

                                        // Explicitly set the inpatient_record field
                                        doc.inpatient_record = frm.doc.name;

                                        // Set the customer field if available
                                        if (patient_data.message && patient_data.message.customer) {
                                            doc.customer = patient_data.message.customer;
                                        }

                                        // Load the doc
                                        frappe.set_route('Form', doc.doctype, doc.name);
                                    }
                                }
                            });
                        }
                    });
                },
                __('Select Request Type'),
                __('Create')
                );
            }, __('Create'));

            // 3. Add primary button for generating bill from service requests
            frm.add_custom_button(__("Bill Service Requests"), function() {
                // Call server-side method to get all service requests with template details
                frappe.call({
                    method: "healthcare.api.get_service_requests_for_billing",
                    args: {
                        inpatient_record: frm.doc.name
                    },
                    freeze: true,
                    freeze_message: __("Fetching Service Requests..."),
                    callback: function(r) {
                        if (r.message && r.message.length > 0) {
                            showServiceRequestSelectionDialog(frm, r.message);
                        } else {
                            frappe.msgprint(__("No unbilled Service Requests found for this Inpatient Record."));
                        }
                    }
                });
            }).addClass("btn-primary");

            // 4. Add button for billing consumables - FIXED PLACEMENT AND USING BILLING STATUS
            frm.add_custom_button(__("Bill Consumables"), function() {
                // Call server-side method to get all consumer requests with template details
                frappe.call({
                    method: "healthcare.api.get_consumer_requests_for_billing",
                    args: {
                        inpatient_record: frm.doc.name
                    },
                    freeze: true,
                    freeze_message: __("Fetching Consumer Requests..."),
                    callback: function(r) {
                        if (r.message && r.message.length > 0) {
                            showConsumerRequestSelectionDialog(frm, r.message);
                        } else {
                            frappe.msgprint(__("No unbilled Consumer Requests found for this Inpatient Record."));
                        }
                    }
                });
            }).addClass("btn-primary");
        }
    }
});

// Function to display the service request selection dialog
function showServiceRequestSelectionDialog(frm, serviceRequests) {
    // Create a simple dialog with a custom table
    let d = new frappe.ui.Dialog({
        title: __("Select Service Requests for Billing"),
        fields: [
            {
                fieldtype: "HTML", 
                fieldname: "service_requests_html"
            }
        ],
        primary_action_label: __("Create Sales Invoice"),
        primary_action: function() {
            let selectedRequests = [];

            // Get all selected service requests
            d.$wrapper.find('input[type="checkbox"]:checked').each(function() {
                let srName = $(this).attr('data-name');
                if (srName) {
                    selectedRequests.push(srName);
                }
            });

            if (selectedRequests.length === 0) {
                frappe.msgprint(__("Please select at least one Service Request."));
                return;
            }

            d.hide();

            // Call server-side method to create sales invoice
            frappe.call({
                method: "healthcare.api.create_sales_invoice_from_service_requests",
                args: {
                    inpatient_record: frm.doc.name,
                    service_requests: selectedRequests
                },
                freeze: true,
                freeze_message: __("Creating Sales Invoice..."),
                callback: function(r) {
                    if (!r.exc && r.message) {
                        if (r.message.count === 0) {
                            frappe.msgprint(__("No Sales Invoice created. Please check if selected services are billable."));
                            return;
                        }

                        // Show success message with invoice link but stay on current page
                        let invoice = r.message.invoices[0];
                        frappe.msgprint({
                            title: __("Success"),
                            indicator: "green",
                            message: __("Sales Invoice {0} created successfully in draft mode. Billing statuses will be updated when you submit the invoice.", 
                                [
                                    `<a href='/app/sales-invoice/${invoice.name}' target='_blank'>${invoice.name}</a>`
                                ]
                            )
                        });

                        // Refresh the current form to reflect any changes
                        frm.refresh();
                    }
                }
            });
        }
    });

    // Create custom HTML for the table
    let html = `
        <div class="service-requests-table">
            <table class="table table-bordered">
                <thead>
                    <tr>
                        <th style="width: 30px;"><input type="checkbox" id="select-all-checkbox"></th>
                        <th>${__("Service Request")}</th>
                        <th>${__("Service")}</th>
                        <th>${__("Date")}</th>
                        <th>${__("Status")}</th>
                        <th>${__("Billing")}</th>
                    </tr>
                </thead>
                <tbody>
                    ${serviceRequests.map((sr, idx) => `
                        <tr>
                            <td>
                                <input type="checkbox" data-name="${sr.name}" class="sr-checkbox" 
                                    ${sr.is_billable === 0 ? 'disabled title="Not billable"' : ''}>
                            </td>
                            <td>${sr.name}</td>
                            <td>${sr.template_dn || ""}</td>
                            <td>${frappe.datetime.str_to_user(sr.order_date)}</td>
                            <td>${sr.status || ""}</td>
                            <td>${sr.billing_status || ""}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>
        <div class="margin-top">
            <div class="row">
                <div class="col-xs-6">
                    <button class="btn btn-xs btn-default select-all">${__("Select All")}</button>
                </div>
                <div class="col-xs-6 text-right">
                    <button class="btn btn-xs btn-default deselect-all">${__("Deselect All")}</button>
                </div>
            </div>
        </div>
    `;

    d.fields_dict.service_requests_html.$wrapper.html(html);

    // Event handlers for select all and deselect all buttons
    d.$wrapper.find('.select-all').on('click', function() {
        d.$wrapper.find('.sr-checkbox:not(:disabled)').prop('checked', true);
        d.$wrapper.find('#select-all-checkbox').prop('checked', true);
    });

    d.$wrapper.find('.deselect-all').on('click', function() {
        d.$wrapper.find('.sr-checkbox').prop('checked', false);
        d.$wrapper.find('#select-all-checkbox').prop('checked', false);
    });

    // Handler for select-all checkbox in the header
    d.$wrapper.find('#select-all-checkbox').on('change', function() {
        let isChecked = $(this).prop('checked');
        d.$wrapper.find('.sr-checkbox:not(:disabled)').prop('checked', isChecked);
    });

    d.show();
}

// Function to display the consumer request selection dialog - IMPROVED WITH BILLING STATUS
function showConsumerRequestSelectionDialog(frm, consumerRequests) {
    // Create a dialog for selecting consumer requests and their items
    let dialog = new frappe.ui.Dialog({
        title: __("Select Consumer Request Items for Billing"),
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'consumer_requests_html'
            }
        ],
        primary_action_label: __("Create Sales Invoice"),
        primary_action: function() {
            // Prepare selected data
            let selectedConsumerRequests = [];

            // Go through each consumer request
            consumerRequests.forEach(cr => {
                let selectedItems = [];

                // Find all selected checkboxes for this consumer request
                dialog.$wrapper.find(`.cr-${cr.name} input[type="checkbox"]:checked`).each(function() {
                    selectedItems.push($(this).attr('data-idx'));
                });

                // If items are selected, add this consumer request to the list
                if (selectedItems.length > 0) {
                    selectedConsumerRequests.push({
                        name: cr.name,
                        selected_items: selectedItems
                    });
                }
            });

            if (selectedConsumerRequests.length === 0) {
                frappe.msgprint(__("Please select at least one item."));
                return;
            }

            dialog.hide();

            // Call server-side method to create sales invoice
            frappe.call({
                method: "healthcare.api.create_sales_invoice_from_consumer_requests",
                args: {
                    inpatient_record: frm.doc.name,
                    consumer_requests: selectedConsumerRequests
                },
                freeze: true,
                freeze_message: __("Creating Sales Invoice..."),
                callback: function(r) {
                    if (!r.exc && r.message) {
                        if (r.message.count === 0) {
                            frappe.msgprint(__("No Sales Invoice created. Please check if selected items are billable."));
                            return;
                        }

                        // Show success message with invoice link but stay on current page
                        let invoice = r.message.invoices[0];
                        frappe.msgprint({
                            title: __("Success"),
                            indicator: "green",
                            message: __("Sales Invoice {0} created successfully in draft mode.", 
                                [
                                    `<a href='/app/sales-invoice/${invoice.name}' target='_blank'>${invoice.name}</a>`
                                ]
                            )
                        });

                        // Refresh the current form to reflect any changes
                        frm.refresh();
                    }
                }
            });
        }
    });

    // Create HTML content for consumer requests and their items
    let html = `
        <div class="consumer-requests-container">
    `;

    // Add each consumer request and its items
    consumerRequests.forEach((cr, crIndex) => {
        html += `
            <div class="consumer-request-section margin-bottom">
                <div class="request-header bold">
                    ${cr.consumer_request_type}: ${cr.name} (${frappe.datetime.str_to_user(cr.transaction_date)})
                    <span class="text-muted">${__("Billing Status")}: ${cr.billing_status || "Pending"}</span>
                </div>
                <div class="request-items">
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th style="width: 30px;">
                                    <input type="checkbox" class="select-all-items" data-cr="${cr.name}">
                                </th>
                                <th>${__("Item")}</th>
                                <th>${__("Quantity")}</th>
                                <th>${__("Rate")}</th>
                                <th>${__("Amount")}</th>
                                <th>${__("Invoiced")}</th>
                            </tr>
                        </thead>
                        <tbody class="cr-${cr.name}">
                            ${cr.items.map((item, idx) => `
                                <tr>
                                    <td>
                                        <input type="checkbox" data-idx="${item.idx}" class="item-checkbox" ${item.invoiced ? 'disabled title="Already invoiced"' : ''}>
                                    </td>
                                    <td>${item.item_name || item.item_code}</td>
                                    <td>${item.quantity}</td>
                                    <td>${frappe.format(item.rate, {fieldtype: 'Currency'})}</td>
                                    <td>${frappe.format(item.amount, {fieldtype: 'Currency'})}</td>
                                    <td>${item.invoiced ? '<span class="indicator green">Yes</span>' : '<span class="indicator orange">No</span>'}</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
    });

    html += `</div>`;

    dialog.fields_dict.consumer_requests_html.$wrapper.html(html);

    // Add event handlers for select all checkboxes
    dialog.$wrapper.find('.select-all-items').on('change', function() {
        let crName = $(this).attr('data-cr');
        let isChecked = $(this).prop('checked');
        dialog.$wrapper.find(`.cr-${crName} input.item-checkbox:not(:disabled)`).prop('checked', isChecked);
    });

    // Add select/deselect all buttons
    let selectButtons = `
        <div class="margin-top">
            <div class="row">
                <div class="col-xs-6">
                    <button class="btn btn-xs btn-default select-all-buttons">${__("Select All Items")}</button>
                </div>
                <div class="col-xs-6 text-right">
                    <button class="btn btn-xs btn-default deselect-all-buttons">${__("Deselect All Items")}</button>
                </div>
            </div>
        </div>
    `;

    dialog.fields_dict.consumer_requests_html.$wrapper.append(selectButtons);

    // Select all items button
    dialog.$wrapper.find('.select-all-buttons').on('click', function() {
        dialog.$wrapper.find('input.item-checkbox:not(:disabled)').prop('checked', true);
        dialog.$wrapper.find('.select-all-items').prop('checked', true);
    });

    // Deselect all items button
    dialog.$wrapper.find('.deselect-all-buttons').on('click', function() {
        dialog.$wrapper.find('input.item-checkbox').prop('checked', false);
        dialog.$wrapper.find('.select-all-items').prop('checked', false);
    });

    dialog.show();
}

