                        label: __('Request Type'),
                        fieldtype: 'Select',
                        options: 'Consumable Request\nBlood Request\nMedicine Request',
                        reqd: 1,
                        default: 'Consumable Request'
                    }
                ],
                function(values) {
                    // First, get the customer associated with the patient
                    frappe.call({
                        method: "frappe.client.get_value",
                        args: {
                            doctype: "Patient",
                            filters: { name: frm.doc.patient },
                            fieldname: ["customer"]
                        },
                        callback: function(patient_data) {
                            // Now create the consumer request
                            frappe.call({
                                method: "healthcare.controllers.inpatient_record_requests.create_consumer_request",
                                args: {
                                    inpatient_record: frm.doc.name,
                                    request_type: values.consumer_request_type
                                },
                                callback: function(r) {
                                    if (r.message) {
                                        // Create a new Consumer Request with pre-filled values
                                        let doc = frappe.model.get_new_doc("Consumer Request");

                                        // Set field values
                                        doc.consumer_request_type = values.consumer_request_type;
                                        doc.patient = frm.doc.patient;
                                        doc.company = frm.doc.company;
                                        doc.transaction_date = frappe.datetime.nowdate();
                                        doc.schedule_date = frappe.datetime.nowdate();
                                        doc.title = `${values.consumer_request_type} for ${frm.doc.patient_name || frm.doc.patient}`;

                                        // Explicitly set the inpatient_record field
                                        doc.inpatient_record = frm.doc.name;

                                        // Set the customer field if available
                                        if (patient_data.message && patient_data.message.customer) {
                                            doc.customer = patient_data.message.customer;
                                        }

                                        // Load the doc
                                        frappe.set_route('Form', doc.doctype, doc.name);
                                    }
                                }
                            });
                        }
                    });
                },
                __('Select Request Type'),
                __('Create')
                );
            }, __('Create'));

            // 3. Add a single Inpatient Billing button
            frm.add_custom_button(__("Inpatient Billing"), function() {
                // Show a dialog to choose billing type
                frappe.prompt([
                    {
                        fieldname: 'billing_type',
                        label: __('Billing Type'),
                        fieldtype: 'Select',
                        options: 'Bill Service Requests\nBill Consumables',
                        reqd: 1,
                        default: 'Bill Service Requests'
                    }
                ],
                function(values) {
                    if (values.billing_type === 'Bill Service Requests') {
                        // Call server-side method to get all service requests with template details
                        frappe.call({
                            method: "healthcare.api.get_service_requests_for_billing",
                            args: {
                                inpatient_record: frm.doc.name
                            },
                            freeze: true,
                            freeze_message: __("Fetching Service Requests..."),
                            callback: function(r) {
                                if (r.message && r.message.length > 0) {
                                    showServiceRequestSelectionDialog(frm, r.message);
                                } else {
                                    frappe.msgprint(__("No unbilled Service Requests found for this Inpatient Record."));
                                }
                            }
                        });
                    } else if (values.billing_type === 'Bill Consumables') {
                        // Call server-side method to get all consumer requests with template details
                        frappe.call({
                            method: "healthcare.api.get_consumer_requests_for_billing",
                            args: {
                                inpatient_record: frm.doc.name
                            },
                            freeze: true,
                            freeze_message: __("Fetching Consumer Requests..."),
                            callback: function(r) {
                                if (r.message && r.message.length > 0) {
                                    showConsumerRequestSelectionDialog(frm, r.message);
                                } else {
                                    frappe.msgprint(__("No unbilled Consumer Requests found for this Inpatient Record."));
                                }
                            }
                        });
                    }
                },
                __('Select Billing Type'),
                __('Continue')
                );
            }).addClass("btn-primary");
        }

        // Add handler for "Show Items" button in the main form
        if (frm.fields_dict.show_items && frm.fields_dict.show_items.$input) {
            frm.fields_dict.show_items.$input.on('click', function() {
                // Find selected rows using a more compatible approach
                let gridField = frm.fields_dict.billables_consumable_requests;
                let grid = gridField.grid;
                let selectedRow = null;

                // Check if there are any rows in the grid
                if (grid && grid.data && grid.data.length > 0) {
                    // First check for visually selected rows (UI selection)
                    if (grid.get_selected) {
                        let selectedIndices = grid.get_selected();
                        if (selectedIndices && selectedIndices.length > 0) {
                            selectedRow = frm.doc.billables_consumable_requests[selectedIndices[0]];
                        }
                    }

                    // If no row is visually selected, check for rows with checked checkbox
                    if (!selectedRow) {
                        // Look for checked rows in the DOM
                        let $checkedRows = $(".grid-row-check:checked", grid.wrapper);
                        if ($checkedRows.length > 0) {
                            // Get the row index from data-idx attribute
                            let idx = $($checkedRows[0]).closest('.grid-row').attr('data-idx');
                            if (idx) {
                                selectedRow = frm.doc.billables_consumable_requests[parseInt(idx) - 1]; // data-idx is 1-based
                            }
                        }
                    }

                    // If a row is selected, show that specific invoice's items
                    if (selectedRow && selectedRow.sales_invoice) {
                        showInvoiceItems(selectedRow.sales_invoice);
                    } else {
                        // If no row is selected but we have invoices, show ALL invoices
                        showInvoiceItems();
                    }
                } else {
                    // If there are billable requests but no selection, show ALL invoices
                    if (frm.doc.billables_consumable_requests && frm.doc.billables_consumable_requests.length > 0) {
                        showInvoiceItems();
                    } else {
                        frappe.msgprint(__("No billable consumable requests found"));
                    }
                }
            });
        }
    }
});

// Function to display the service request selection dialog
function showServiceRequestSelectionDialog(frm, serviceRequests) {
