// Function to display a dialog to select a consumable request when no row is selected
function showConsumableInvoiceDialog(frm) {
    // Check if there are any billable consumable requests
    if (!frm.doc.billables_consumable_requests || frm.doc.billables_consumable_requests.length === 0) {
        frappe.msgprint(__("No billable consumable requests found"));
        return;
    }

    // Create a dialog to select a consumable request
    let consumable_requests = frm.doc.billables_consumable_requests.map(cr => {
        return {
            label: `${cr.request_type} - ${cr.consumer_requests} (${cr.sales_invoice})`,
            value: cr.sales_invoice,
            request_type: cr.request_type,
            consumer_request: cr.consumer_requests
        };
    });

    let d = new frappe.ui.Dialog({
        title: __("Select Consumable Request"),
        fields: [
            {
                fieldtype: "Select",
                fieldname: "sales_invoice",
                label: __("Sales Invoice"),
                options: consumable_requests.map(cr => cr.value),
                reqd: 1,
                description: __("Select a sales invoice to view its items"),
                onchange: function() {
                    // Find the selected consumable request
                    let selected = consumable_requests.find(cr => cr.value === d.get_value("sales_invoice"));
                    if (selected) {
                        d.set_value("request_info", `${selected.request_type} - ${selected.consumer_request}`);
                    }
                }
            },
            {
                fieldtype: "HTML",
                fieldname: "request_info",
                label: __("Request Info")
            }
        ],
        primary_action_label: __("Show Items"),
        primary_action: function() {
            let selected_invoice = d.get_value("sales_invoice");

            if (!selected_invoice) {
                frappe.msgprint(__("Please select a sales invoice"));
                return;
            }

            d.hide();
            showInvoiceItems(selected_invoice);
        }
    });

    d.show();
}

// Function to fetch and display invoice items
function showInvoiceItems(sales_invoice) {
    // If no specific invoice is selected, we'll fetch items from all invoices
    const fetchAllInvoices = !sales_invoice;

    // Call the API to get sales invoice items
    frappe.call({
        method: fetchAllInvoices ? 
            "healthcare.api.get_all_sales_invoice_items" : 
            "healthcare.api.get_sales_invoice_items",
        args: fetchAllInvoices ? 
            { inpatient_record: cur_frm.doc.name } : 
            { sales_invoice: sales_invoice },
        freeze: true,
        freeze_message: __("Fetching Invoice Items..."),
        callback: function(r) {
            console.log("Invoice items response:", r);

            if (r.message) {
                if (fetchAllInvoices) {
                    show_all_invoice_items_dialog(r.message);
                } else {
                    show_invoice_items_dialog(r.message);
                }
            }
        }
    });
}

